-- Emerald Encrusted Chest 10752 (Kum'isha's Endeavors 25772): always one blue and one green, level 41-50.
-- Before: 41 independent rows (ten blue and ten green references rolled one by one, 155.8 % in all). About 20 % of
-- chests were empty, 26 % held two or more blues and 64 % had no green.
-- Retail: one blue and one green per chest (NorseGhost 2012-03-02, comment 998592 2012-07-06). Wowhead MoP Classic
-- sample (3647 chests): 0.956 blues and 0.404 greens per chest, the 50 blues and 128 greens seen are all in the pools below.
-- A reference row cannot be grouped in this core (LootTemplate::AddEntry), so the blues become a direct equal-chance
-- group (group 1, chance 0) and the greens one reference of the chest's own (id 10752, unused before).
-- Item lists are copied from the shared references 754,1203,1720,2564,5266,6660,7734,11302,13018,13035 (blues) and
-- 1608,1639,1994,3208,7517,8106,8246,8251,8254,8269 (greens); those shared references are not changed.
-- Kept as independent rows: 16 direct items (epics, gems, blue plans) and references 3395, 3914, 7975, 12684, 12693.

DELETE FROM `reference_loot_template` WHERE `entry` = 10752;

DELETE FROM `item_loot_template` WHERE `entry` = 10752 AND (`groupid` = 1 OR `mincountOrRef` IN
(-754,-1203,-1720,-2564,-5266,-6660,-7734,-11302,-13018,-13035,
 -1608,-1639,-1994,-3208,-7517,-8106,-8246,-8251,-8254,-8269,-10752));
